# Sites in the stock image that load the half-press target keys as immediates.
# The encoding checked is the one in the home builder: fc cc <u32 key>.
# Do not edit this file after it has run.
from pathlib import Path

ROOT = Path('.')
IMAGE = ROOT / 'inputs/00_0100_50000020.decoded.bin'
OUT = ROOT / 'work/out/static-keys-m1.txt'
BASE = 0x60021020
KEYS = {
    0x99A1: 'zone type',
    0x9A41: 'target size',
    0x5962: 'position',
    0x1DD1: 'custom size',
    0x1DE1: 'custom step',
    0xDFA1: 'home size',
    0x99D2: 'home position',
    0x1DB1: 'area orientation enable',
    0x1DC1: 'position orientation enable',
    0x0E91: 'pose',
}

image = IMAGE.read_bytes()
lines = ['# fc cc + little-endian key immediate', f'# image {IMAGE.as_posix()} bytes {len(image)}']
for key, name in KEYS.items():
    pat = bytes([0xFC, 0xCC]) + key.to_bytes(4, 'little')
    hits = []
    start = 0
    while True:
        o = image.find(pat, start)
        if o < 0:
            break
        hits.append(o)
        start = o + 1
    lines.append(f'\n## 0x{key:04x} {name}  hits {len(hits)}')
    for o in hits:
        addr = BASE + o
        window = image[o:o + 16].hex()
        lines.append(f'{addr:08x}  {window}')

# ASCII names that identify the target-selection screen.
needles = [b'AF_Target', b'af_target', b'Target_Actuator', b'Plural_AF', b'SELECT_AF']
lines.append('\n# strings')
for needle in needles:
    start = 0
    n = 0
    while n < 20:
        o = image.find(needle, start)
        if o < 0:
            break
        end = image.find(b'\x00', o)
        text = image[o:end if end > o else o + 80]
        lines.append(f'{BASE + o:08x}  {text[:120]!r}')
        start = o + 1
        n += 1
    if n == 0:
        lines.append(f'miss {needle!r}')

OUT.parent.mkdir(parents=True, exist_ok=True)
OUT.write_text('\n'.join(lines) + '\n', encoding='utf-8')
print('\n'.join(lines[:80]))
print('... total lines', len(lines))
